# Apply rule: 0 changes to 8 if it has edge-connected 0 neighbor
def has_edge_connected_0(r, c, grid):
    """Check if this cell has at least one 4-direction (edge) neighbor that is also 0."""
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 13 and 0 <= nc < 13:
            if grid[nr][nc] == 0:
                return True
    return False

