# Save the function and grid for later submission
def transform(grid):
    """Transform: 0 becomes 8 if it has an edge-connected 0 neighbor."""
    height = len(grid)
    width = len(grid[0])
    output = [row[:] for row in grid]

    for r in range(height):
        for c in range(width):
            if grid[r][c] == 0:
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < height and 0 <= nc < width:
                        if grid[nr][nc] == 0:
                            output[r][c] = 8
                            break
    return output

